{
  "categoryId": "{{catId}}",
  "listingType": "BOTH",
  "version": 1,
  "isActive": true,
  "title": {
    "en": "List Equipment",
    "hi": "उपकरण सूचीबद्ध करें"
  },
  "fields": [
    {
      "fieldKey": "equipmentType",
      "type": "DROPDOWN",
      "label": {
        "en": "Equipment Type",
        "hi": "उपकरण प्रकार"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": true,
      "displayOrder": 10,
      "optionSetKey": "equipment__equipment_type"
    },
    {
      "fieldKey": "equipmentName",
      "type": "DROPDOWN",
      "label": {
        "en": "Equipment Name",
        "hi": "उपकरण का नाम"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": true,
      "displayOrder": 20,
      "optionSetKey": "equipment__equipment_name",
      "allowOther": true
    },
    {
      "fieldKey": "equipmentNameOther",
      "type": "TEXT",
      "label": {
        "en": "Please Specify",
        "hi": "कृपया निर्दिष्ट करें"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": false,
      "displayOrder": 30,
      "fieldLength": 80,
      "validation": {
        "maxLength": 80
      },
      "visibleWhen": {
        "field": "equipmentName",
        "operator": "equals",
        "value": "__other__"
      }
    },
    {
      "fieldKey": "availableFor",
      "type": "RADIO",
      "label": {
        "en": "Available For",
        "hi": "उपलब्ध है"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": true,
      "displayOrder": 40,
      "optionSetKey": "equipment__avail"
    },
    {
      "fieldKey": "rentPerHour",
      "type": "DECIMAL",
      "label": {
        "en": "Rent Per Hour (₹)",
        "hi": "प्रति घंटा किराया (₹)"
      },
      "sectionKey": "rent",
      "sectionTitle": {
        "en": "Rental",
        "hi": "किराया"
      },
      "required": false,
      "displayOrder": 50,
      "validation": {
        "min": 0
      },
      "visibleWhen": {
        "field": "availableFor",
        "operator": "equals",
        "value": "rent"
      }
    },
    {
      "fieldKey": "brandName",
      "type": "TEXT",
      "label": {
        "en": "Brand Name",
        "hi": "ब्रांड नाम"
      },
      "sectionKey": "seller",
      "sectionTitle": {
        "en": "Seller Details",
        "hi": "विक्रेता विवरण"
      },
      "required": false,
      "displayOrder": 60,
      "fieldLength": 80,
      "validation": {
        "maxLength": 80
      },
      "visibleWhen": {
        "field": "availableFor",
        "operator": "equals",
        "value": "sell"
      }
    },
    {
      "fieldKey": "modelNumber",
      "type": "TEXT",
      "label": {
        "en": "Model Number",
        "hi": "मॉडल नंबर"
      },
      "sectionKey": "seller",
      "sectionTitle": {
        "en": "Seller Details",
        "hi": "विक्रेता विवरण"
      },
      "required": false,
      "displayOrder": 70,
      "fieldLength": 60,
      "validation": {
        "maxLength": 60
      },
      "visibleWhen": {
        "field": "availableFor",
        "operator": "equals",
        "value": "sell"
      }
    },
    {
      "fieldKey": "modelYear",
      "type": "NUMBER",
      "label": {
        "en": "Model Year",
        "hi": "मॉडल वर्ष"
      },
      "sectionKey": "seller",
      "sectionTitle": {
        "en": "Seller Details",
        "hi": "विक्रेता विवरण"
      },
      "required": false,
      "displayOrder": 80,
      "visibleWhen": {
        "field": "availableFor",
        "operator": "equals",
        "value": "sell"
      }
    },
    {
      "fieldKey": "availableQty",
      "type": "NUMBER",
      "label": {
        "en": "Available Quantity",
        "hi": "उपलब्ध मात्रा"
      },
      "sectionKey": "quantity",
      "sectionTitle": {
        "en": "Quantity & Unit",
        "hi": "मात्रा और इकाई"
      },
      "required": true,
      "displayOrder": 90,
      "validation": {
        "min": 1
      }
    },
    {
      "fieldKey": "actualPrice",
      "type": "DECIMAL",
      "label": {
        "en": "Actual Price (₹)",
        "hi": "वास्तविक मूल्य (₹)"
      },
      "sectionKey": "pricing",
      "sectionTitle": {
        "en": "Pricing",
        "hi": "मूल्य निर्धारण"
      },
      "required": true,
      "displayOrder": 100,
      "common": true,
      "validation": {
        "min": 0
      },
      "visibleWhen": {
        "field": "availableFor",
        "operator": "equals",
        "value": "sell"
      }
    },
    {
      "fieldKey": "offeredPrice",
      "type": "DECIMAL",
      "label": {
        "en": "Offered Price (₹)",
        "hi": "प्रस्तावित मूल्य (₹)"
      },
      "sectionKey": "pricing",
      "sectionTitle": {
        "en": "Pricing",
        "hi": "मूल्य निर्धारण"
      },
      "required": true,
      "displayOrder": 110,
      "common": true,
      "validation": {
        "min": 0
      },
      "visibleWhen": {
        "field": "availableFor",
        "operator": "equals",
        "value": "sell"
      }
    },
    {
      "fieldKey": "discountPct",
      "type": "AUTO_CALC",
      "label": {
        "en": "Discount %",
        "hi": "छूट %"
      },
      "sectionKey": "pricing",
      "sectionTitle": {
        "en": "Pricing",
        "hi": "मूल्य निर्धारण"
      },
      "required": false,
      "displayOrder": 120,
      "common": true,
      "readOnly": true,
      "computed": {
        "formula": "(actualPrice - offeredPrice) / actualPrice * 100",
        "readOnly": true
      }
    },
    {
      "fieldKey": "isNegotiable",
      "type": "BOOLEAN",
      "label": {
        "en": "Is Negotiable?",
        "hi": "क्या मोल-भाव योग्य है?"
      },
      "sectionKey": "pricing",
      "sectionTitle": {
        "en": "Pricing",
        "hi": "मूल्य निर्धारण"
      },
      "required": false,
      "displayOrder": 130,
      "common": true
    },
    {
      "fieldKey": "images",
      "type": "IMAGE",
      "label": {
        "en": "Upload Images",
        "hi": "तस्वीरें अपलोड करें"
      },
      "sectionKey": "media",
      "sectionTitle": {
        "en": "Photos",
        "hi": "तस्वीरें"
      },
      "required": true,
      "displayOrder": 140,
      "multiple": true,
      "common": true,
      "validation": {
        "min": 1,
        "max": 10,
        "acceptedTypes": [
          "jpg",
          "png",
          "webp"
        ],
        "sources": [
          "camera",
          "gallery"
        ],
        "capture": true
      }
    },
    {
      "fieldKey": "useDefaultAddress",
      "type": "BOOLEAN",
      "label": {
        "en": "Use Default Address",
        "hi": "डिफ़ॉल्ट पते का उपयोग करें"
      },
      "sectionKey": "address",
      "sectionTitle": {
        "en": "Address",
        "hi": "पता"
      },
      "required": false,
      "displayOrder": 150,
      "common": true
    },
    {
      "fieldKey": "address",
      "type": "ADDRESS",
      "label": {
        "en": "Address",
        "hi": "पता"
      },
      "sectionKey": "address",
      "sectionTitle": {
        "en": "Address",
        "hi": "पता"
      },
      "required": true,
      "displayOrder": 160,
      "common": true,
      "visibleWhen": {
        "field": "useDefaultAddress",
        "operator": "equals",
        "value": false
      }
    }
  ]
}

